head.b:skin:
/*
-----------------------------------------------
Theme: mrxshahin.ai.studio Official Blogger Theme
Layout Version: 3.0
-----------------------------------------------
*/
body {
  margin: 0;
  padding: 0;
  font-family: 'Plus Jakarta Sans', sans-serif;
}
.post-body {
  font-size: 1.05rem;
  line-height: 1.8;
}
.post-body p {
  margin-bottom: 1.5rem;
}
.post-body h2, .post-body h3 {
  font-weight: 700;
  margin-top: 1.75rem;
  margin-bottom: 0.75rem;
}
.post-body img {
  max-width: 100%;
  height: auto;
  border-radius: 0.75rem;
  margin: 1.5rem auto;
  display: block;
}
.post-body a {
  color: #d97706;
  text-decoration: underline;
  font-weight: 600;
}

body.script:
/*  */
function toggleTheme() {
  var html = document.documentElement;
  if (html.classList.contains('dark')) {
    html.classList.remove('dark');
    localStorage.setItem('studio_theme', 'light');
  } else {
    html.classList.add('dark');
    localStorage.setItem('studio_theme', 'dark');
  }
}
(function() {
  if (localStorage.getItem('studio_theme') === 'dark') {
    document.documentElement.classList.add('dark');
  }
  var yEl = document.getElementById('yearSpan');
  if (yEl) yEl.textContent = new Date().getFullYear();
})();
/*  */
